"""
    Use the information that 0 and 1 color will be close for us and info about the frequencies of similar objects
    to change the colors to new ones
    Args:
        colors: dict, old coloring

    Returns:
        dict, new coloring, that uses that 0 and 1 is close colors
    """
def recolor_by_frequency(colors: dict) -> dict {
    replace_dict = {
        val: ind
        for (ind, val) in enumerate(
            sorted(
                `set(colors.values()),
                key=lambda (x: Any) { `list(colors.values()).count(colors[x]); }
            )
        )
    };
    result_dict = {};
    for key in colors {
        result_dict[key] = replace_dict[colors[key]];
    }
    return result_dict;
}

"""
    Normalize the grant and/or revoke lists we were given. Handle single item, list of items, etc.
    We want to end up with just a list of IDs. Used by Project object to handle modify_access function.

    :param acl: a list of Person objects or just a Person object
    :return: a list of integers representing the IDs of the Person objects in the list given
    """
def normalize_acl(acl: Any) -> object {
    try {
        acl = [int(a) for a in acl];
    } except TypeError {
        acl = [int(acl)];
    }
    return acl;
}

